import{_ as o,C as r,o as a,c as s,j as d,a as n,E as c,a2 as i}from"./chunks/framework.DCaeQ2Kp.js";const S=JSON.parse('{"title":"回合状态机","description":"","frontmatter":{},"headers":[],"relativePath":"guide/runtime.md","filePath":"guide/runtime.md"}'),l={name:"guide/runtime.md"};function h(m,t,g,u,b,_){const e=r("DiagramFrame");return a(),s("div",null,[t[0]||(t[0]=d("h1",{id:"回合状态机",tabindex:"-1"},[n("回合状态机 "),d("a",{class:"header-anchor",href:"#回合状态机","aria-label":'Permalink to "回合状态机"'},"​")],-1)),t[1]||(t[1]=d("p",null,"momod（Rust 编排器）的运行时核心：五态状态机 + 取消令牌 + 句切 + 队列背压 + 延迟预算。",-1)),c(e,{src:"turn-states.html",height:560}),t[2]||(t[2]=i('<h2 id="各状态进入动作" tabindex="-1">各状态进入动作 <a class="header-anchor" href="#各状态进入动作" aria-label="Permalink to &quot;各状态进入动作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>进入动作</th></tr></thead><tbody><tr><td><code>Idle</code></td><td>重置 idle 计时器；广播 <code>state.turn{idle}</code></td></tr><tr><td><code>Listening</code></td><td>绑定新 <code>turn_id</code>；ASR 接收音频；广播</td></tr><tr><td><code>Thinking</code></td><td>建取消令牌；组装历史+人设 prompt → 发起 LLM 流</td></tr><tr><td><code>Speaking</code></td><td>句切器消费 token 流 → <code>output.sentence</code> 双发（UI+TTS）</td></tr><tr><td><code>Interrupted</code></td><td>执行 <a href="/momo/guide/barge-in">barge-in 三动作</a></td></tr></tbody></table><p><strong>自发开口</strong>：<code>Idle</code> 持续 <code>MOMO_IDLE_TIMEOUT_S</code>（默认 20s，0=关闭）→ 注入情境直接进 <code>Thinking</code>。连续自发最多 1 次防刷屏。</p><h2 id="句切规则-按序应用" tabindex="-1">句切规则（按序应用） <a class="header-anchor" href="#句切规则-按序应用" aria-label="Permalink to &quot;句切规则（按序应用）&quot;">​</a></h2><ol><li><strong>强切</strong>：<code>。！？!?；;…</code> 或换行立即成句；ASCII <code>.</code>/<code>!</code>/<code>?</code> 仅后随空白/流结束才切（避免 <code>Mr.</code>、<code>3.14</code> 误切）</li><li><strong>弱切</strong>：<code>,，、</code> + 缓冲 ≥25 字（<code>MOMO_SENT_SOFT_CHARS</code>）——防长句饿死首包</li><li><strong>硬切</strong>：60 字（<code>MOMO_SENT_MAX_CHARS</code>）无标点强制成句</li><li><strong>tag 剥离</strong>：<code>[xxx]</code> 先移除再计长；表外值归一 <code>neutral</code></li><li><strong>收尾</strong>：流结束 flush <code>final:true</code>；空回复直接回 <code>Idle</code></li><li><strong>语言</strong>：每句主导语言检测写 <code>lang</code> 提示 TTS；v1 不按语言拆句</li></ol><h2 id="队列与背压" tabindex="-1">队列与背压 <a class="header-anchor" href="#队列与背压" aria-label="Permalink to &quot;队列与背压&quot;">​</a></h2><table tabindex="0"><thead><tr><th>队列</th><th>容量</th><th>溢出策略</th></tr></thead><tbody><tr><td>mic 上行（orch→ASR）</td><td>2s 音频</td><td>丢旧帧 + 日志</td></tr><tr><td><code>sentence_q</code></td><td>8 句</td><td>暂停读 LLM 流（反压）</td></tr><tr><td>TTS 在途</td><td>1 句并发</td><td>逐句串行保序</td></tr><tr><td>下行音频</td><td>96 帧 ≈4.8s</td><td>溢出→<code>BACKPRESSURE_OVERFLOW</code>+取消回合</td></tr><tr><td>VAD 段上限</td><td>30s</td><td>ASR 侧强制 final</td></tr></tbody></table><h2 id="延迟预算-目标-1-5s-出声" tabindex="-1">延迟预算（目标 &lt;1.5s 出声） <a class="header-anchor" href="#延迟预算-目标-1-5s-出声" aria-label="Permalink to &quot;延迟预算（目标 &lt;1.5s 出声）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>语音回合</th><th>依据</th></tr></thead><tbody><tr><td>VAD 判停</td><td>250 ms</td><td>silero <code>silence_ms</code></td></tr><tr><td>ASR 转写</td><td>~150 ms（3s 语音）</td><td><strong>实测</strong> RTF 0.040</td></tr><tr><td>编排开销</td><td>20 ms</td><td>目标值</td></tr><tr><td>LLM 首 token</td><td>300 ms</td><td><strong>预估</strong>；30B 实测 121 t/s</td></tr><tr><td>首句成形</td><td>200 ms</td><td>~25 tok 推算</td></tr><tr><td>TTS 首 chunk</td><td>250 ms</td><td>Kokoro <strong>实测</strong> 209 ms</td></tr><tr><td>网络+jitter</td><td>100 ms</td><td>LAN</td></tr><tr><td><strong>合计</strong></td><td><strong>~1.3 s</strong></td><td>余量 ~200ms</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">权威来源</p><p><a href="https://github.com/Momoyeyu/momo-docs/blob/master/01-architecture/runtime.md" target="_blank" rel="noreferrer">momo-docs/01-architecture/runtime.md</a> — 取消令牌树、模块布局、完整预算表。</p></div>',10))])}const T=o(l,[["render",h]]);export{S as __pageData,T as default};
